package com.vandorlabs.client;

import com.google.gson.*;
import com.vandorlabs.blocks.*;
import com.vandorlabs.persistence.ProgrammableGlassSettings;
import com.vandorlabs.tiles.TileEntityProgrammableGlass;
import java.io.*;
import java.util.*;
import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.*;
import net.minecraft.util.math.*;

/** Actual released flat-glass metadata, bounds, placement and missing-size load callbacks. */
public final class ProgrammableGlassLegacyOracle {
 private static final BlockPos POS=new BlockPos(8,80,8);
 private static JsonObject state(BlockProgrammableGlass glass,IBlockState state){JsonObject out=new JsonObject();out.addProperty("rotated",state.getValue(BlockGlassWall.ROTATED));out.addProperty("depth",state.getValue(BlockGlassWall.DEPTH));out.addProperty("size",state.getValue(BlockProgrammableGlass.SIZE));out.addProperty("encoded",glass.getMetaFromState(state));return out;}
 private static JsonObject settings(ProgrammableGlassSettings s){JsonObject out=new JsonObject();out.addProperty("shade",s.shade);out.addProperty("material",s.material);out.addProperty("layout",s.layout);out.addProperty("effectiveLayout",s.textureLayout());out.addProperty("stretch",s.stretch);out.addProperty("tint",s.tint);out.addProperty("framed",s.framed);out.addProperty("size",s.size);out.addProperty("join",s.join);out.addProperty("panelFacing",s.panelFacing);out.addProperty("legacySize",s.legacySize);return out;}
 private static NBTTagCompound input(int profile){NBTTagCompound out=new NBTTagCompound();switch(profile){case 0:break;case 1:out.setInteger("GlassSize",0);break;case 2:out.setInteger("GlassSize",2);break;case 3:out.setByte("GlassSize",(byte)0);break;case 4:out.setString("GlassSize","0");break;case 5:out.setInteger("GlassSize",-1);break;case 6:out.setInteger("GlassSize",99);break;case 7:out.setInteger("GlassShade",-1);out.setInteger("GlassTint",-1);break;case 8:out.setInteger("GlassShade",99);out.setInteger("GlassTint",99);break;case 9:out.setString("GlassShade","2");out.setString("GlassTint","0");break;case 10:out.setBoolean("GlassStretch",true);break;case 11:out.setInteger("GlassTextureLayout",0);break;case 12:out.setInteger("GlassTextureLayout",2);break;case 13:out.setInteger("GlassTextureLayout",99);out.setBoolean("GlassStretch",true);break;case 14:out.setString("GlassFramed","true");out.setString("GlassJoin","true");break;case 15:out.setBoolean("GlassFramed",false);out.setBoolean("GlassJoin",false);break;case 16:out.setInteger("GlassPanelFacing",-1);break;case 17:out.setInteger("GlassPanelFacing",5);break;case 18:out.setByte("GlassPanelFacing",(byte)2);break;default:out.setInteger("GlassMaterial",new int[]{-3,-1,0,9,14,64,Integer.MAX_VALUE}[profile-19]);break;}return out;}
 public static void main(String[] args)throws Exception {
  PropulsionPlacementLegacyOracle.initialize();BlockProgrammableGlass glass=null;BlockProgrammableWall wall=null,diagonal=null;for(net.minecraft.block.Block block:ModBlocks.BLOCKS){if(block instanceof BlockProgrammableGlass)glass=(BlockProgrammableGlass)block;if(block instanceof BlockProgrammableWall&&block.getRegistryName().getResourcePath().equals("programmable_wall"))wall=(BlockProgrammableWall)block;}for(net.minecraft.block.Block block:ModBlocks.BLOCKS)if(block.getRegistryName().getResourcePath().equals("programmable_diagonal_wall"))diagonal=(BlockProgrammableWall)block;if(glass==null||wall==null||diagonal==null)throw new AssertionError("Released panel catalog");
  NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);EntityPlayer actor=new EntityPlayer(world,new com.mojang.authlib.GameProfile(UUID.fromString("99584022-32e4-4ae5-820f-2bc481c102c1"),"GlassOracle")){public boolean isCreative(){return false;}public boolean isSpectator(){return false;}};Gson gson=new Gson();File file=new File(args[0]);file.getAbsoluteFile().getParentFile().mkdirs();int metadata=0,loads=0,placements=0;
  try(PrintWriter out=new PrintWriter(file,"UTF-8")){
   for(int meta=-1;meta<=17;meta++){IBlockState state=glass.getStateFromMeta(meta);world.clear();world.states.put(POS,state);JsonObject row=new JsonObject();row.addProperty("kind","metadata");row.addProperty("meta",meta);row.add("state",state(glass,state));AxisAlignedBB box=glass.getBoundingBox(state,world,POS);JsonArray bounds=new JsonArray();for(double value:new double[]{box.minX,box.minY,box.minZ,box.maxX,box.maxY,box.maxZ})bounds.add(value);row.add("bounds",bounds);out.println(gson.toJson(row));metadata++;
    for(int profile=0;profile<26;profile++){NBTTagCompound tag=input(profile);TileEntityProgrammableGlass tile=new TileEntityProgrammableGlass();tile.readFromNBT(tag);tile.setWorld(world);tile.setPos(POS);world.tiles.put(POS,tile);JsonObject loaded=new JsonObject();loaded.addProperty("kind","load");loaded.addProperty("meta",meta);loaded.addProperty("profile",profile);loaded.addProperty("tag",tag.toString());loaded.add("before",settings(tile.settings()));tile.onLoad();loaded.add("after",settings(tile.settings()));out.println(gson.toJson(loaded));loads++;world.tiles.clear();}
   }
   float[] hit={0,Math.nextDown(1F/3F),1F/3F,Math.nextUp(1F/3F),Math.nextDown(2F/3F),2F/3F,Math.nextUp(2F/3F),1};
   for(int facing=0;facing<4;facing++)for(EnumFacing side:EnumFacing.values())for(float x:hit)for(float z:hit)for(int neighbor=0;neighbor<43;neighbor++){world.clear();actor.rotationYaw=EnumFacing.getHorizontal(facing).getHorizontalAngle();IBlockState clicked=null;if(neighbor>0&&neighbor<7)clicked=glass.getDefaultState().withProperty(BlockGlassWall.ROTATED,neighbor>3).withProperty(BlockGlassWall.DEPTH,(neighbor-1)%3);else if(neighbor>=7&&neighbor<19)clicked=wall.getDefaultState().withProperty(BlockProgrammableWall.FACING,EnumFacing.getHorizontal((neighbor-7)/3)).withProperty(BlockProgrammableWall.DEPTH,(neighbor-7)%3);if(neighbor>=19){int diagonalProfile=neighbor-19;clicked=diagonal.getDefaultState().withProperty(BlockProgrammableWall.FACING,EnumFacing.getHorizontal(diagonalProfile/6)).withProperty(BlockProgrammableWall.INVERTED,(diagonalProfile%6&1)!=0);com.vandorlabs.tiles.TileEntityAnimatedScreenSelector tile=new com.vandorlabs.tiles.TileEntityAnimatedScreenSelector();tile.setDiagonalGeometry(diagonalProfile%6/2,0);tile.setWorld(world);tile.setPos(POS.offset(side.getOpposite()));world.tiles.put(tile.getPos(),tile);}if(clicked!=null)world.states.put(POS.offset(side.getOpposite()),clicked);JsonObject row=new JsonObject();row.addProperty("kind","placement");row.addProperty("facing",facing);row.addProperty("side",side.getIndex());row.addProperty("x",x);row.addProperty("z",z);row.addProperty("neighbor",neighbor);row.add("state",state(glass,glass.getStateForPlacement(world,POS,side,x,.625F,z,0,actor,EnumHand.MAIN_HAND)));out.println(gson.toJson(row));placements++;}
  }
  System.out.println("Actual programmable glass source PASS metadata="+metadata+" loads="+loads+" placements="+placements+" file="+file);
 }
}
